pub fn init(gpa: std.mem.Allocator, m: *Model) Lanes {
    var ln: Lanes = .{ .gpa = gpa, .m = m, .peer = if (m.world > 1) m.peer() else null };
    if (m.dr) |dr| ln.win_rows = @min(window_rows, dr.n_most + 1); // TF_DS_DRAFT_BLOCK widens it (draft.blockFromEnv)
    if (std.c.getenv("TF_DS_DRAFT_BLOCK_KEPT")) |v| ln.wide_kept = std.fmt.parseInt(usize, std.mem.trim(u8, std.mem.span(v), " "), 10) catch ln.wide_kept;
    ln.keep_protect = api.prompt_cache.keepProtect(if (std.c.getenv("TF_DS_KEEP_PROTECT")) |v| std.mem.span(v) else null); // every rank alike
    ln.accept_chain = envOne("TF_DS_DEVICE_ACCEPT"); // every rank alike; an uneven pair is still bit-identical (the follower never reads the keep)
    if (m.triage != null and ln.accept_chain) {
        // (0177: the dead rows' device keep counts would count garbage picks; the host's accept treats them as rejected)
        ln.accept_chain = false;
        std.log.warn("dsv41: TF_DS_DEVICE_ACCEPT is off under TF_DS_DRAFT_TRIAGE", .{});
    }
    // the round costs by rows: ROUND_MS[min(rows, len) - 1] (the served table, or TF_DS_ROUND_MS)
    const t = m.round_ms;
    for (&ln.wc, 0..) |*c, i| c.* = .{ .width = @intCast(i + 1), .ms = t[@min(i, t.len - 1)] };
    for (&ln.sc, 0..) |*c, i| c.* = .{ .width = @intCast(i + 1), .ms = t[@min(i, t.len - 1)] };
    return ln;
}

/// Tells rank 1 to stop, then frees the host state (the model is the caller's).
pub fn deinit(self: *Lanes) void {
    self.stopKv();
    for (self.snaps.items) |sn| {
        sn.buf.free();
        if (sn.tail) |*b| b.free();
        self.gpa.destroy(sn);
    }
    self.snaps.deinit(self.gpa);
    if (self.peer != null) self.send(.done) catch {};
    if (self.rw) |l| self.gpa.destroy(l); // (after the tier and the planner that borrowed it)
    self.rw = null;
    self.streams.deinit(self.gpa);
    for (&self.seqs) |*q| q.deinit(self.gpa);
    self.wire.deinit(self.gpa);
    if (self.spec_sx) |x| self.gpa.destroy(x);
    self.spec_sx = null;
}

pub fn backend(self: *Lanes) be.Backend {
    return .{ .ptr = self, .vtable = &.{
        .prefill = prefillFn,
        .prefill_part = prefillPartFn,
        .first = firstFn,
        .queue = queueFn,
        .read = readFn,
        .verify = verifyFn,
        .keep = keepFn,
        .draft = draftFn,
        .probabilities = probabilitiesFn,
        .release = releaseFn,
        .ordinal = ordinalFn,
    } };
}

/// The wire's frame ordinal: the frame rank 0 last sent. Rank 1 checks each frame's step (`error.OutOfStep`), so
/// both sides count the same ordinals, and a request's window joins the follower's per-frame counter exactly.
fn ordinalFn(ptr: *anyopaque) u64 {
    return of(ptr).step;
}

/// The facts the round loop reads: windows of the pending row and up to the drafter's block, several streams'
/// windows in one forward of at most 16 rows (four streams), the drafter's chances, the served lane's round ms.
pub fn facts(self: *const Lanes) lanes.Model {
    const drafting = self.m.drafting();
    return .{
        .exact_width = @intCast(self.win_rows),
        .gpu_tokens = false,
        .mtp = drafting,
        .speculate = drafting,
        .speculate_early = false,
        .drafts = if (self.m.dr) |dr| @intCast(dr.n_most) else 1,
        .window_costs = self.wc[0..self.win_rows],
        .mtp_step_ms = draft.draft_ms,
        .solo_head_overhead_ms = if (drafting and self.solo_overhead) draft.draft_ms else null, // opt-in: the Python engine's fixed draft allowance
        .allocate_learned = self.allocate_learned,
        .draft_cal = self.draft_cal,
        .cal_log = self.cal_log,
        .draft_pin = self.draft_pin,
        .copy_proposals = !(drafting and self.no_copies), // opt-in: the draft head proposes; the Python engine makes no copies either
        .streams_exact = true,
        .hidden_rows = true,
        .batch_rows = @intCast(self.m.eng.round_rows),
        .max_streams = @intCast(self.m.streams),
        .shared_costs = self.sc[0..self.m.eng.round_rows],
        .draft_probabilities = drafting,
        .draft_streams = drafting,
    };
}

