/// Commit the target-sampled path (after the thinking budget's cut); the kept rows and their following tokens.
fn conclude(e: *Engine, s: *Stream, p: Plan, sampled: []const u32, tokens: []const u32, parents: []const i32, positions: []const u64, device_keep: ?u32) !Outcome {
